import sqlite3
import pandas as pd
import json

# Connect to the database
conn = sqlite3.connect('dacomp-034.sqlite')
cursor = conn.cursor()

# Get table names
cursor.execute("SELECT name FROM sqlite_master WHERE type='table';")
tables = cursor.fetchall()

print("Tables in database:")
for table in tables:
    print(f"- {table[0]}")

# Check each table for Explanation column
for table_name in [t[0] for t in tables]:
    # Handle table names with special characters by quoting them
    try:
        # Try with quotes for tables with special characters
        cursor.execute(f'PRAGMA table_info("{table_name}")')
    except:
        # If that fails, try without quotes (for simple table names)
        try:
            cursor.execute(f"PRAGMA table_info({table_name})")
        except:
            print(f"Could not get column info for table: {table_name}")
            continue

    columns = cursor.fetchall()
    column_names = [col[1] for col in columns]

    if 'Explanation' in column_names:
        print(f"\nFound 'Explanation' column in table: {table_name}")

        # Read the Explanation column data
        try:
            # Use quotes for table name in query
            df = pd.read_sql_query(f'SELECT Explanation FROM "{table_name}"', conn)
        except:
            # Try without quotes if that fails
            df = pd.read_sql_query(f'SELECT Explanation FROM {table_name}', conn)

        print(f"\nNumber of rows with Explanation: {len(df)}")
        print(f"Number of non-null explanations: {df['Explanation'].notna().sum()}")

        # Show sample explanations
        print("\nSample Explanation values (first 5 non-null):")
        non_null_explanations = df['Explanation'].dropna()
        for i, explanation in enumerate(non_null_explanations.head(5)):
            print(f"\n{i+1}. {str(explanation)[:300]}..." if len(str(explanation)) > 300 else f"{i+1}. {explanation}")

        # Analyze content structure
        print("\nAnalyzing Explanation content structure...")

        # Check data types and patterns
        explanation_types = {}
        for explanation in non_null_explanations:
            exp_str = str(explanation)
            if exp_str.strip().startswith('{') and exp_str.strip().endswith('}'):
                explanation_types['JSON-like'] = explanation_types.get('JSON-like', 0) + 1
            elif exp_str.strip().startswith('[') and exp_str.strip().endswith(']'):
                explanation_types['Array-like'] = explanation_types.get('Array-like', 0) + 1
            else:
                explanation_types['Plain text'] = explanation_types.get('Plain text', 0) + 1

        print("\nExplanation content types:")
        for exp_type, count in explanation_types.items():
            print(f"  {exp_type}: {count}")

        # Try to parse JSON-like explanations
        json_parsed = []
        for explanation in non_null_explanations:
            exp_str = str(explanation).strip()
            if exp_str.startswith('{') and exp_str.endswith('}'):
                try:
                    parsed = json.loads(exp_str)
                    json_parsed.append(parsed)
                except json.JSONDecodeError:
                    pass

        if json_parsed:
            print(f"\nSuccessfully parsed {len(json_parsed)} JSON explanations")

            # Analyze structure of parsed JSON
            all_keys = set()
            for parsed in json_parsed:
                all_keys.update(parsed.keys())

            print(f"\nKeys found in JSON explanations: {sorted(all_keys)}")

            # Look for active session scope and permitted columns
            session_scopes = set()
            permitted_columns_list = []

            for parsed in json_parsed:
                # Check for active session scope
                for key in ['active_session_scope', 'session_scope', 'scope', 'activeScope']:
                    if key in parsed:
                        session_scopes.add(str(parsed[key]))

                # Check for permitted columns
                for key in ['permitted_columns', 'columns', 'allowed_columns', 'permittedColumns']:
                    if key in parsed:
                        if isinstance(parsed[key], list):
                            permitted_columns_list.extend(parsed[key])
                        elif isinstance(parsed[key], str):
                            permitted_columns_list.append(parsed[key])

            if session_scopes:
                print(f"\nActive session scopes found: {sorted(session_scopes)}")

            if permitted_columns_list:
                print(f"\nPermitted columns found: {sorted(set(permitted_columns_list))}")

            # Show a sample JSON structure
            if json_parsed:
                print("\nSample JSON structure:")
                print(json.dumps(json_parsed[0], indent=2))

        break  # Stop after finding first table with Explanation column

conn.close()
